package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	// 静态目录要真实存在，先建好再挂
	if err := os.MkdirAll("./static", 0o755); err != nil {
		panic(err)
	}
	if err := os.WriteFile("./static/hello.txt", []byte("hello"), 0o644); err != nil {
		panic(err)
	}

	r := gin.New()
	r.Static("/static", "./static")

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/static/hello.txt", nil))
	fmt.Println(w.Code, w.Body.String())
}

package main

import (
	"fmt"
	"net/http"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	// 注册路由时的 panic 由这里接住
	defer func() {
		if rec := recover(); rec != nil {
			fmt.Println("路由冲突 panic:", rec)
		}
	}()

	r := gin.New()
	r.GET("/static/:name", func(c *gin.Context) { c.String(http.StatusOK, "ok") })
	// Static 注册的是 /static/*filepath，和上面的 :name 在同一层，冲突
	r.Static("/static", "./static")
	fmt.Println("没有冲突")
}

