import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	// 静态目录不存在：注册时不 panic，请求时返回 404
	r := gin.New()
	r.Static("/static", "./missing")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/static/a.txt", nil))
	fmt.Println("静态目录不存在 ->", w.Code)

	// 模板目录不存在：加载时直接 panic
	defer func() {
		if rec := recover(); rec != nil {
			fmt.Println("模板目录不存在 panic:", rec)
		}
	}()
	r2 := gin.New()
	r2.LoadHTMLGlob("./templates/*.html")
	fmt.Println("不会走到这里")
}

