package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"

	"github.com/gin-gonic/gin"
)

// 统一错误响应中间件
func ErrorMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Next()
		if len(c.Errors) == 0 || c.Writer.Written() {
			return
		}
		c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{
			"code":    "INTERNAL_ERROR",
			"message": c.Errors.Last().Err.Error(),
			"path":    c.Request.URL.Path,
		})
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)

	// 准备静态资源和模板
	_ = os.MkdirAll("./static", 0o755)
	_ = os.WriteFile("./static/logo.txt", []byte("logo"), 0o644)
	_ = os.MkdirAll("./templates", 0o755)
	_ = os.WriteFile("./templates/index.html", []byte("<h1>{{.title}}</h1>"), 0o644)

	r := gin.New()
	r.Use(ErrorMiddleware())
	r.Use(gin.CustomRecovery(func(c *gin.Context, err any) {
		c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{"error": "服务器内部错误"})
	}))

	r.LoadHTMLGlob("./templates/*.html")
	r.GET("/", func(c *gin.Context) {
		c.HTML(http.StatusOK, "index.html", gin.H{"title": "首页"})
	})
	r.Static("/static", "./static")

	api := r.Group("/api")
	api.GET("/users/:id", func(c *gin.Context) {
		if c.Param("id") != "1" {
			_ = c.Error(errors.New("用户不存在"))
			c.Abort()
			return
		}
		c.JSON(http.StatusOK, gin.H{"id": 1, "name": "张三"})
	})

	r.HandleMethodNotAllowed = true
	r.NoRoute(func(c *gin.Context) {
		c.AbortWithStatusJSON(http.StatusNotFound, gin.H{"error": "资源不存在", "path": c.Request.URL.Path})
	})
	r.NoMethod(func(c *gin.Context) {
		c.AbortWithStatusJSON(http.StatusMethodNotAllowed, gin.H{"error": "方法不被允许"})
	})

	for _, path := range []string{"/", "/static/logo.txt", "/api/users/1", "/api/users/2", "/nope"} {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
		fmt.Printf("GET %-18s -> %d %s\n", path, w.Code, w.Body.String())
	}
}
